1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	const CURSE_SURCHARGE_PERCENT = 50;
53	const HIGH_ENCHANTMENT_LEVEL = 5;
54	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
55	const LOYALTY_YEARS = 2;
56	const LOYALTY_DISCOUNT_PERCENT = 20;
57	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
58	
59	/** What the MHPCO knows about a kind of item it will insure: what insuring
60	 *  one costs (`basePremium`), and what one is insured FOR (`insuranceValue`,
61	 *  from which the cap is derived — never from premiums). One entry per kind,
62	 *  so the two figures for a kind cannot drift apart. */
63	interface ItemKind {
64	  basePremium: number;
65	  insuranceValue: number;
66	}
67	
68	/** The MHPCO's price list. */
69	const ITEM_KINDS: Record<string, ItemKind> = {
70	  sword: { basePremium: 100, insuranceValue: 1000 },
71	  amulet: { basePremium: 60, insuranceValue: 600 },
72	  staff: { basePremium: 80, insuranceValue: 800 },
73	  potion: { basePremium: 40, insuranceValue: 400 },
74	  rune: { basePremium: 25, insuranceValue: 250 },
75	  moonstone: { basePremium: 25, insuranceValue: 250 },
76	};
77	
78	const basePremiumOfType = (type: string): number =>
79	  ITEM_KINDS[type].basePremium;
80	
81	const insuranceValueOfType = (type: string): number =>
82	  ITEM_KINDS[type].insuranceValue;
83	
84	const DEDUCTIBLE_PER_DAMAGED_ITEM = 100;
85	const CAP_MULTIPLE = 2;
86	
87	/** The enchantment level from which a CLAIM is only half reimbursed. Distinct
88	 *  from HIGH_ENCHANTMENT_LEVEL, which is the premium surcharge threshold. */
89	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
90	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
91	
92	/** Modifiers are expressed as an amount to add, never as a factor to multiply
93	 *  by, so that they stay additive against their base and so that the integer
94	 *  numerator keeps float artifacts out of the final rounding
95	 *  (100 * 1.1 === 110.000…1, but (100 * 10) / 100 === 10 exactly). */
96	const percentOf = (amount: number, percent: number): number =>
97	  (amount * percent) / 100;
98	
99	/** Rounds up — premiums round in the MHPCO's favour. */
100	const roundPremium = (amount: number): number => Math.ceil(amount);
101	
102	const COMPONENT_BLOCK_SIZE = 3;
103	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
104	
105	const COMPONENT_TYPES = ["rune", "moonstone"];
106	
107	const isComponent = (item: Item): boolean =>
108	  COMPONENT_TYPES.includes(item.type);
109	
110	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
111	
112	const countByType = (items: Item[]): Map<string, number> => {
113	  const counts = new Map<string, number>();
114	  for (const item of items) {
115	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
116	  }
117	  return counts;
118	};
119	
120	/** A block is exactly three alike components, priced as a unit rather than
121	 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
122	const componentGroupBasePremium = ([type, count]: [string, number]): number =>
123	  count === COMPONENT_BLOCK_SIZE
124	    ? COMPONENT_BLOCK_BASE_PREMIUM
125	    : count * basePremiumOfType(type);
126	
127	const sum = (amounts: number[]): number =>
128	  amounts.reduce((total, amount) => total + amount, 0);
129	
130	const policyBasePremium = (items: Item[]): number => {
131	  const mainItems = items.filter((item) => !isComponent(item));
132	  const componentGroups = [...countByType(items.filter(isComponent))];
133	
134	  return (
135	    sum(mainItems.map(itemBasePremium)) +
136	    sum(componentGroups.map(componentGroupBasePremium))
137	  );
138	};
139	
140	interface ItemModifierRule {
141	  appliesTo: (item: Item) => boolean;
142	  percent: number;
143	}
144	
145	/** Every item-scoped modifier, as a rule that either applies to an item or
146	 *  does not. Applicable rules stack. */
147	const ITEM_MODIFIER_RULES: ItemModifierRule[] = [
148	  {
149	    appliesTo: (item) => item.cursed === true,
150	    percent: CURSE_SURCHARGE_PERCENT,
151	  },
152	  {
153	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
154	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
155	  },
156	];
157	
158	/** Item-scoped modifiers apply to the affected item's own base premium,
159	 *  not to the policy total. */
160	const itemModifierAmount = (item: Item): number =>
161	  sum(
162	    ITEM_MODIFIER_RULES.filter((rule) => rule.appliesTo(item)).map((rule) =>
163	      percentOf(itemBasePremium(item), rule.percent),
164	    ),
165	  );
166	
167	/** A policy written by a quote step, as later claim steps see it. The insured
168	 *  items are kept because a damage entry names only a type, while the clauses
169	 *  that govern its reimbursement depend on the insured item itself. */
170	interface Policy {
171	  remainingCap: number;
172	  items: Item[];
173	}
174	
175	/** What a step leaves behind for the steps after it. Steps are not
176	 *  independent: a quote is priced against how many contracts precede it, and
177	 *  a claim is paid against a policy an earlier quote wrote, so running a
178	 *  scenario threads this state from each step to the next. */
179	interface ScenarioState {
180	  customer: Customer;
181	  precedingContracts: number;
182	  /** Keyed by the zero-based index of the quote step that wrote the policy —
183	   *  which is what a claim step's `policy` field refers to. */
184	  policiesByStep: Record<number, Policy>;
185	}
186	
187	const initialState = (customer: Customer): ScenarioState => ({
188	  customer,
189	  precedingContracts: 0,
190	  policiesByStep: {},
191	});
192	
193	/** A step's outcome: what it reports, and the state the next step sees. */
194	interface StepOutcome {
195	  result: StepResult;
196	  state: ScenarioState;
197	}
198	
199	/** What a policy-wide rule may look at: the customer, plus where this quote
200	 *  sits in the customer's history of contracts. A pricing view of the
201	 *  scenario state — rules read it, they never advance it. */
202	type PolicyContext = Readonly<ScenarioState>;
203	
204	interface PolicyModifierRule {
205	  appliesTo: (context: PolicyContext) => boolean;
206	  /** Signed: positive surcharges, negative discounts. */
207	  percent: number;
208	}
209	
210	/** Every policy-wide modifier, as a rule that either applies to a policy or
211	 *  does not. Applicable rules stack. */
212	const POLICY_MODIFIER_RULES: PolicyModifierRule[] = [
213	  {
214	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
215	    percent: -LOYALTY_DISCOUNT_PERCENT,
216	  },
217	  {
218	    appliesTo: () => true,
219	    percent: FIRST_INSURANCE_SURCHARGE_PERCENT,
220	  },
221	  {
222	    appliesTo: ({ precedingContracts }) => precedingContracts > 0,
223	    percent: -FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
224	  },
225	];
226	
227	/** Policy-wide modifiers apply to the policy base premium — the sum of every
228	 *  item's base premium — not to any single item. */
229	const policyModifierAmount = (
230	  basePremium: number,
231	  context: PolicyContext,
232	): number =>
233	  sum(
234	    POLICY_MODIFIER_RULES.filter((rule) => rule.appliesTo(context)).map(
235	      (rule) => percentOf(basePremium, rule.percent),
236	    ),
237	  );
238	
239	const quote = (items: Item[], context: PolicyContext): QuoteResult => {
240	  const basePremium = policyBasePremium(items);
241	  // Every modifier is an amount added to the base premium, not a factor
242	  // compounded onto a running total: item-scoped modifiers take a percentage
243	  // of their own item's base premium, policy-wide ones take a percentage of
244	  // the policy base premium.
245	  const modifierAmounts = [
246	    ...items.map(itemModifierAmount),
247	    policyModifierAmount(basePremium, context),
248	  ];
249	  // The processing fee is added last, after all percentage modifiers.
250	  const premium = basePremium + sum(modifierAmounts) + PROCESSING_FEE;
251	  return { premium: roundPremium(premium) };
252	};
253	
254	/** The cap on everything a policy will ever pay out: twice the sum of the
255	 *  insured items' values. Premium modifiers do not raise it. */
256	const policyCap = (items: Item[]): number =>
257	  CAP_MULTIPLE * sum(items.map((item) => insuranceValueOfType(item.type)));
258	
259	/** What one damage entry reimburses before the deductible: the full damage,
260	 *  unless a special clause reduces it. */
261	const reimbursableDamage = (damage: Damage, insuredItem: Item): number =>
262	  (insuredItem.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL
263	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
264	    : damage.amount;
265	
266	/** What one damage entry reimburses: the reimbursable damage, less the
267	 *  deductible that is charged once per damaged item. */
268	const damageReimbursement = (damage: Damage, policy: Policy): number => {
269	  const insuredItem = policy.items.find(
270	    (item) => item.type === damage.itemType,
271	  ) as Item;
272	  return reimbursableDamage(damage, insuredItem) - DEDUCTIBLE_PER_DAMAGED_ITEM;
273	};
274	
275	/** The state that results from recording one policy against a step index,
276	 *  replacing any policy already recorded there. */
277	const withPolicy = (
278	  state: ScenarioState,
279	  stepIndex: number,
280	  policy: Policy,
281	): ScenarioState => ({
282	  ...state,
283	  policiesByStep: { ...state.policiesByStep, [stepIndex]: policy },
284	});
285	
286	/** Writes a policy, and records it so later claim steps can be paid against
287	 *  it. Each quote written also becomes a preceding contract for the next. */
288	const runQuote = (
289	  step: QuoteStep,
290	  stepIndex: number,
291	  state: ScenarioState,
292	): StepOutcome => ({
293	  result: quote(step.items, state),
294	  state: withPolicy(
295	    { ...state, precedingContracts: state.precedingContracts + 1 },
296	    stepIndex,
297	    { remainingCap: policyCap(step.items), items: step.items },
298	  ),
299	});
300	
301	/** Pays a claim against the policy an earlier quote step wrote, drawing the
302	 *  payout down from that policy's remaining cap. */
303	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
304	  const policy = state.policiesByStep[step.policy];
305	  const payout = sum(
306	    step.incident.damages.map((damage) => damageReimbursement(damage, policy)),
307	  );
308	  const remainingCap = policy.remainingCap - payout;
309	  return {
310	    result: { payout, remainingCap },
311	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
312	  };
313	};
314	
315	const runStep = (
316	  step: Step,
317	  stepIndex: number,
318	  state: ScenarioState,
319	): StepOutcome =>
320	  step.op === "quote"
321	    ? runQuote(step, stepIndex, state)
322	    : runClaim(step, state);
323	
324	export const runScenario = (scenario: Scenario): ScenarioResult => {
325	  const { results } = scenario.steps.reduce(
326	    ({ results, state }, step, stepIndex) => {
327	      const outcome = runStep(step, stepIndex, state);
328	      return { results: [...results, outcome.result], state: outcome.state };
329	    },
330	    { results: [] as StepResult[], state: initialState(scenario.customer) },
331	  );
332	  return { results };
333	};
